\begin{ex}%[9H9N1-1]
\immini[thm]{
Hình nào dưới đây vẽ một góc nội tiếp của đường tròn?.
}{
\begin{tikzpicture}[>=stealth,line join=round,line cap=round,font=\footnotesize,scale=1]
        %\clip (-2.4,-2.3) rectangle (2.4,4.6);
        \path 
        (0,0) coordinate (O)
        ($(O) + (-30:1.7)$) coordinate (A)
        ($(O) + (-115:1.7)$) coordinate (B)
        ;
        \draw (O) circle (1.7cm);
        \draw (A)--(O)--(B);
        \foreach \x in {O,A,B}\fill[black] (\x) circle (1pt);
        \fill (0,-2.1) node[below]{a)};
        % hinh b
        \path 
        (4.5,0) coordinate (O1)
        ($(O1) + (110:1.7)$) coordinate (A1)
        ($(A1) + (0,0.6)$) coordinate (a)
        ($(O1) + (-30:1.7)$) coordinate (B1)
        ($(O1) + (-115:1.7)$) coordinate (C1)
        ;
        \draw (O1) circle (1.7cm);
        \draw (B1)--(a)--(C1);
        \foreach \x in {O1,a,B1,C1}\fill[black] (\x) circle (1pt);
        \fill (5,-2.1) node[below]{b)};
        % hinh c
        \path 
        (9,0) coordinate (O2)
        ($(O2) + (110:1.7)$) coordinate (A2)
        ($(O2) + (-30:1.7)$) coordinate (B2)
        ($(O2) + (-115:1.7)$) coordinate (C2)
        ;
        \draw (O2) circle (1.7cm);
        \draw (B2)--(A2)--(C2);
        \foreach \x in {O2,A2,B2,C2}\fill[black] (\x) circle (1pt);
        \fill (9,-2.1) node[below]{c)};
        % hinh d
        \path 
        (13.5,0) coordinate (O3)
        ($(O3) + (90:1.7)$) coordinate (A3)
        ($(A3) + (0,-0.6)$) coordinate (a3)
        ($(O3) + (-90:1.7)$) coordinate (B3)
        ($(O3) + (-130:1.7)$) coordinate (C3)
        ;
        \draw (O3) circle (1.7cm);
        \draw (B3)--(a3)--(C3);
        \foreach \x in {O3,a3,B3,C3}\fill[black] (\x) circle (1pt);
        \fill (13.5,-2.1) node[below]{d)};
    \end{tikzpicture}
}
\loigiai{
Hình a, b, d đều vẽ góc có đỉnh không nằm trên đường tròn nên đó không phải là góc nội tiếp đường tròn. Hình c vẽ góc có đỉnh nằm trên đường tròn và hai cạnh chứa hai dây cung của đường tròn nên là góc nội tiếp đường tròn.
}\end{ex}
